.control
* Run transient analysis to observe SC CMFB settling
tran 0.1n 400n uic

let vocm = (v(vop) + v(vom)) / 2
let vocmd = (v(vopd) + v(vomd)) / 2
let pwr = -i(VDD) * 1.8

meas tran v_ocm_final find vocm at=395n
meas tran v_ocmd_final find vocmd at=395n
meas tran v_cmfb1_final find v(VCMFB1) at=395n
meas tran v_cmfb2_final find v(VCMFB2) at=395n
meas tran v_bias1_val find v(Vbias1) at=395n
meas tran pwr_avg avg pwr from=200n to=400n

print v_ocm_final v_ocmd_final v_cmfb1_final v_cmfb2_final pwr_avg

quit
.endc
.end

